  auto args = fmt_create_arg_store();
  ASSERT_NE(nullptr, args);

  fmt_add_long(args, 1000000L);
  fmt_add_ulong(args, 2000000UL);
  char* result = fmt_format("{} {}", args);
  EXPECT_STREQ("1000000 2000000", result);
  free(result);

  fmt_free_arg_store(args);
}

