    fprintf(stderr, "Failed to format string\n");
    fmt_free_arg_store(args);
    return 1;
  }

  // Print the result
  printf("%s\n", result);

  // Clean up
  free(result);
  fmt_free_arg_store(args);

  return 0;
}

